s=(r/'bin/verify-database-keys-guides.py').read_text().replace('==20','==21').replace('Inspect primary foreign and unique keys','Inspect indexes and performance evidence').replace('Resolve captured key membership and references','Capture index structures and SQL reference evidence').replace('database-keys-guide-check','database-indexes-guide-check');(r/'bin/verify-database-indexes-guides.py').write_text(s)
